package com.luisdavid.clientservice.adapter.output.persistence;
import com.luisdavid.clientservice.adapter.output.persistence.entity.ClientEntity; import com.luisdavid.clientservice.adapter.output.persistence.repository.SpringDataClientRepository; import com.luisdavid.clientservice.application.port.output.IClientRepository; import com.luisdavid.clientservice.domain.model.Client; import org.springframework.stereotype.Component; import java.util.*;
@Component public class ClientPersistenceAdapter implements IClientRepository { private final SpringDataClientRepository repository; public ClientPersistenceAdapter(SpringDataClientRepository r){repository=r;} public Client save(Client c){return toDomain(repository.save(toEntity(c)));} public Optional<Client> findById(Long id){return repository.findById(id).map(this::toDomain);} public List<Client> findAll(){return repository.findAll().stream().map(this::toDomain).toList();} private ClientEntity toEntity(Client c){return new ClientEntity(c.id(),c.fullName(),c.email(),c.createdAt());} private Client toDomain(ClientEntity c){return new Client(c.getId(),c.getFullName(),c.getEmail(),c.getCreatedAt());}}
